import{_ as i,o,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Tenant API v1 — Invoices","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Invoices | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-invoices"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Invoices | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-invoices"}]]},"headers":[],"relativePath":"api/tenant-v1-invoices.md","filePath":"api/tenant-v1-invoices.md","lastUpdated":1785713264000}'),a={name:"api/tenant-v1-invoices.md"};function n(d,e,c,r,l,p){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="tenant-api-v1-—-invoices" tabindex="-1">Tenant API v1 — Invoices <a class="header-anchor" href="#tenant-api-v1-—-invoices" aria-label="Permalink to &quot;Tenant API v1 — Invoices&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:invoices</code>, plus permission middleware / policies.</p><blockquote><p><strong>Naming:</strong> the model is <code>CustomerInvoice</code> — a tenant&#39;s invoices to <em>its own</em> customers. Central&#39;s own platform-billing <code>Invoice</code>/<code>tenant-v1-...</code> endpoints for subscription invoices are unrelated.</p></blockquote><p>Assignee scoping: without <code>invoices.assign</code> (and not superadmin), list/stats/view/update/<strong>send</strong>/<strong>void</strong> only include invoices where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-invoices-stats" tabindex="-1">GET <code>/invoices/stats</code> <a class="header-anchor" href="#get-invoices-stats" aria-label="Permalink to &quot;GET `/invoices/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_invoices&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_invoices&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;partial&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;paid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;void&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;overdue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;outstanding_balance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>overdue</code> / <code>outstanding_balance</code> only consider invoices with <code>status</code> in <code>sent</code>/<code>partial</code> and (for <code>overdue</code>) <code>due_date</code> in the past with <code>balance_due &gt; 0</code>.</p><h2 id="invoices-crud" tabindex="-1">Invoices CRUD <a class="header-anchor" href="#invoices-crud" aria-label="Permalink to &quot;Invoices CRUD&quot;">​</a></h2><h3 id="get-invoices" tabindex="-1">GET <code>/invoices</code> <a class="header-anchor" href="#get-invoices" aria-label="Permalink to &quot;GET `/invoices`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>title</code> or <code>number</code>), <code>status</code>, <code>contact_id</code>, <code>company_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_invoices</code>, <code>overdue</code> (<code>true</code>), <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>currency</code>, <code>subtotal</code>/<code>tax_total</code>/<code>total</code>/<code>amount_paid</code>/<code>amount_credited</code>/<code>balance_due</code>, <code>issue_date</code>/<code>due_date</code>, <code>contact</code>/<code>company</code>/<code>quotation</code> refs, assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-invoices" tabindex="-1">POST <code>/invoices</code> <a class="header-anchor" href="#post-invoices" aria-label="Permalink to &quot;POST `/invoices`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>notes</code>, <code>currency</code> (3-letter, default <code>USD</code>), <code>issue_date</code>, <code>due_date</code> (dates), <code>contact_id</code>, <code>company_id</code> (optional, module-entitlement + assignee-scope validated via <code>LinkableContact</code>/<code>LinkableCompany</code>), <code>quotation_id</code> (optional, tenant-scoped existence check only), <code>assigned_to</code>, <code>lines</code> (array of <code>{ description, quantity, unit_price, tax_rate, sort_order }</code>).</p><p><code>subtotal</code>, <code>tax_total</code>, <code>total</code>, and <code>balance_due</code> are computed server-side from <code>lines</code> — do not send them. Status always starts at <code>draft</code>; <code>number</code> is auto-generated (<code>INV-00001</code>, configurable prefix).</p><h3 id="get-invoices-id" tabindex="-1">GET <code>/invoices/{id}</code> <a class="header-anchor" href="#get-invoices-id" aria-label="Permalink to &quot;GET `/invoices/{id}`&quot;">​</a></h3><p>Includes contact, company, quotation, assignee, creator, lines, notes, and timeline activities.</p><h3 id="put-invoices-id" tabindex="-1">PUT <code>/invoices/{id}</code> <a class="header-anchor" href="#put-invoices-id" aria-label="Permalink to &quot;PUT `/invoices/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> invoices only. Sending <code>lines</code> replaces the full line-item set and recalculates totals. Non-draft invoices return 422 on <code>status</code> (<code>Only draft invoices can be edited.</code>). Assignment after send uses <code>POST /invoices/{id}/assign</code>.</p><h3 id="delete-invoices-id" tabindex="-1">DELETE <code>/invoices/{id}</code> <a class="header-anchor" href="#delete-invoices-id" aria-label="Permalink to &quot;DELETE `/invoices/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>invoices.delete</code>.</p><h3 id="post-invoices-id-restore" tabindex="-1">POST <code>/invoices/{id}/restore</code> <a class="header-anchor" href="#post-invoices-id-restore" aria-label="Permalink to &quot;POST `/invoices/{id}/restore`&quot;">​</a></h3><p>Permission: <code>invoices.restore</code>.</p><h3 id="delete-invoices-id-force" tabindex="-1">DELETE <code>/invoices/{id}/force</code> <a class="header-anchor" href="#delete-invoices-id-force" aria-label="Permalink to &quot;DELETE `/invoices/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted invoice. Permission: <code>invoices.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-invoices-id-assign" tabindex="-1">POST <code>/invoices/{id}/assign</code> <a class="header-anchor" href="#post-invoices-id-assign" aria-label="Permalink to &quot;POST `/invoices/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>invoices.assign</code>.</p><h3 id="post-invoices-id-send" tabindex="-1">POST <code>/invoices/{id}/send</code> <a class="header-anchor" href="#post-invoices-id-send" aria-label="Permalink to &quot;POST `/invoices/{id}/send`&quot;">​</a></h3><p>Transitions <code>draft → sent</code>. Backfills <code>issue_date</code> to today if unset. Permission: <code>invoices.send</code> (assignee-scoped unless the actor has <code>invoices.assign</code> or is superadmin). <strong>Status-only</strong> — does not email or generate a PDF.</p><h3 id="post-invoices-id-void" tabindex="-1">POST <code>/invoices/{id}/void</code> <a class="header-anchor" href="#post-invoices-id-void" aria-label="Permalink to &quot;POST `/invoices/{id}/void`&quot;">​</a></h3><p>Transitions <code>draft|sent → void</code>. <strong>Ledger guard:</strong> rejected with a 422 on <code>status</code> (naming the invoice number) if <code>amount_paid &gt; 0</code> (void the posted payments first) or <code>amount_credited &gt; 0</code> (applied credit notes cannot be reversed, so a credited invoice can never be voided). Since an invoice only reaches <code>partial</code> once one of those is non-zero, <code>Partial → Void</code> is not an allowed transition at all. Permission: <code>invoices.void</code> (assignee-scoped unless the actor has <code>invoices.assign</code> or is superadmin).</p><h3 id="post-invoices-id-status" tabindex="-1">POST <code>/invoices/{id}/status</code> <a class="header-anchor" href="#post-invoices-id-status" aria-label="Permalink to &quot;POST `/invoices/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;sent&quot;|&quot;partial&quot;|&quot;paid&quot;|&quot;void&quot; }</code></p><p>Authorization depends on the target status:</p><ul><li><code>sent</code> → <code>invoices.send</code></li><li><code>void</code> → <code>invoices.void</code></li><li>other allowed transitions → <code>invoices.update</code></li></ul><p>Rejects disallowed transitions with a 422 validation error on <code>status</code>. <code>partial</code>/<code>paid</code> transitions are allowed here for completeness, but in practice are driven by <a href="/api/tenant-v1-payments">Payments</a> posting/voiding rather than direct user action. Applying a <a href="/api/tenant-v1-credit-notes">Credit Note</a> credits <code>amount_credited</code>/<code>balance_due</code> directly and does not go through this endpoint. A <code>void</code> target is routed through the same ledger guard as <code>POST /invoices/{id}/void</code> (see above) — it is not a bare enum transition. Records a <code>status_changed</code> timeline entry (plus a <code>voided</code> entry when the target is <code>void</code>).</p><h3 id="post-invoices-id-notes" tabindex="-1">POST <code>/invoices/{id}/notes</code> <a class="header-anchor" href="#post-invoices-id-notes" aria-label="Permalink to &quot;POST `/invoices/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>invoices.update</code>.</p><h3 id="get-invoices-id-timeline" tabindex="-1">GET <code>/invoices/{id}/timeline</code> <a class="header-anchor" href="#get-invoices-id-timeline" aria-label="Permalink to &quot;GET `/invoices/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>note_added</code>, <code>voided</code>, <code>deleted</code>, <code>restored</code>).</p>',45)])])}const v=i(a,[["render",n]]);export{u as __pageData,v as default};
